import{_ as t,o as e,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Publish Instagram Reels","description":"","frontmatter":{},"headers":[],"relativePath":"feature/publishing-social/3-8-13-publish-instagram-reels/spec.md","filePath":"feature/publishing-social/3-8-13-publish-instagram-reels/spec.md"}'),o={name:"feature/publishing-social/3-8-13-publish-instagram-reels/spec.md"};function r(l,a,h,s,c,d){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="uc-—-publish-instagram-reels" tabindex="-1">UC — Publish Instagram Reels <a class="header-anchor" href="#uc-—-publish-instagram-reels" aria-label="Permalink to &quot;UC — Publish Instagram Reels&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.8.13</td></tr><tr><td>Feature</td><td>Publish Instagram Reels</td></tr><tr><td>Domain</td><td>Publishing &amp; Social (FR 3.8)</td></tr><tr><td>Role</td><td>MEMBER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Tự động đăng Reels lên Instagram qua API chính thức, khi Task loại Post đã hoàn thành Approval Sequence.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Member, tôi muốn hệ thống tự động đăng Reels lên Instagram, để không cần đăng tay thủ công.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Task loại <code>post</code> đạt trạng thái <code>COMPLETED</code> (qua Approval Sequence, FR 3.6.9) và có <code>targetPlatform=Instagram</code> → vào hàng đợi publish.</li><li>Publisher service gọi API chính thức của Instagram bằng token đã connect (FR 3.8.1) để đăng Reels.</li><li>Kết quả cập nhật vào View Status Tracking (FR 3.8.8): <code>PENDING → IN_PROGRESS → DONE</code>/<code>FAIL</code>.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Không có UI riêng — publish tự động, chỉ hiển thị kết quả qua Status Tracking (FR 3.8.8) và Dashboard (FR 3.8.3).</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(internal) POST /internal/publisher/instagram/publish</span></span>
<span class="line"><span>{ &quot;taskId&quot;, &quot;content&quot;, &quot;mediaUrls&quot; }</span></span>
<span class="line"><span>→ 200 { &quot;platformPostId&quot;, &quot;postUrl&quot; } hoặc lỗi platform cụ thể</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Token Instagram hết hạn/bị revoke → <code>FAIL</code>, lý do <code>TOKEN_EXPIRED</code>, thông báo Client cần reconnect (FR 3.8.1).</li><li>Nội dung vi phạm giới hạn platform (độ dài, định dạng media) → <code>FAIL</code> với lý do cụ thể từ API platform.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Client disconnect account đúng lúc bài đang trong hàng đợi publish → xem Edge Case ở FR 3.8.2 (Post chuyển FAIL rõ lý do).</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Publish Reels lên Instagram thành công qua API thật, trạng thái cập nhật đúng.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/07-publishing-social-collaborator.html">07-publishing-social-collaborator.md</a></p>`,22)])])}const g=t(o,[["render",r]]);export{p as __pageData,g as default};
